<script setup>
import {ref,reactive,onMounted,onBeforeUnmount} from 'vue'
import L from 'leaflet'
import MapIcon from './components/MapIcon.vue'
const props=defineProps({sharedMap:Object,trafficContext:Object})
const emit=defineEmits(['close'])
const mapEl=ref(null),panel=ref(false),query=ref(''),focused=ref('place'),suggestions=ref([]),place=ref(null),picking=ref(''),mode=ref('bike'),ai=ref(false),preference=ref(''),messages=ref([]),error=ref(''),parkingError=ref(''),busy=ref(false),result=ref(null),recommendations=ref([])
const endpoints=reactive({origin:{text:'',point:null},destination:{text:'',point:null}})
const showParking=ref(true),showBus=ref(false),parkingItems=ref([]),bus=ref({routes:[],stops:[],vehicles:[]})
let map,roads,markers,routeLayer,parkingLayer,percentLayer,busLayer,observer,timer,searchTimer,searchId=0,runId=0,stopped=false
async function api(path,body){const r=await fetch('/api'+path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(60000)});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'请求失败');return d}
function invalidate(){runId++;result.value=null;recommendations.value=[];routeLayer?.clearLayers();error.value='';parkingError.value='';if(parkingLayer)drawParking()}
function drawMarkers(){markers?.clearLayers();for(const [key,e] of Object.entries(endpoints)){if(!e.point)continue;const name=document.createElement('span');name.textContent=e.text;L.circleMarker([e.point.latitude,e.point.longitude],{pane:'navigation-markers',radius:8,color:'white',weight:3,fillColor:key==='origin'?'#1a73e8':'#e94235',fillOpacity:1}).bindTooltip(name).addTo(markers)}}
function search(key){if(key!=='place'){endpoints[key].point=null;invalidate();drawMarkers()}focused.value=key;const value=key==='place'?query.value:endpoints[key].text;const token=++searchId;suggestions.value=[];clearTimeout(searchTimer);if(!value.trim())return;searchTimer=setTimeout(async()=>{try{const d=await api('/navigation/places?q='+encodeURIComponent(value));if(token===searchId&&!stopped)suggestions.value=d.items}catch(e){if(token===searchId)error.value=e.message}},220)}
function choose(key,item){searchId++;suggestions.value=[];focused.value='';picking.value='';invalidate();const e={text:item.name,point:{latitude:item.latitude,longitude:item.longitude}};if(key==='place'){place.value=item;query.value=item.name;endpoints.destination=e}else endpoints[key]=e;drawMarkers();map.panTo([item.latitude,item.longitude]);if(endpoints.destination.point&&!result.value)nearby()}
function directions(){panel.value=true;focused.value='';suggestions.value=[]}
function openAI(){directions();ai.value=true;picking.value='';suggestions.value=[];focused.value=''}
async function chatNavigate(){
 const text=preference.value.trim();if(!text||busy.value)return
 invalidate();busy.value=true;const token=runId
 messages.value.push({role:'user',content:text});preference.value=''
 try{const d=await api('/navigation/chat',{messages:messages.value.slice(-12),traffic_context:props.trafficContext})
  if(token!==runId||stopped)return
  messages.value.push({role:'assistant',content:d.reply})
  if(d.status==='route'){
   endpoints.origin={text:d.origin.name,point:{latitude:d.origin.latitude,longitude:d.origin.longitude}}
   endpoints.destination={text:d.destination.name,point:{latitude:d.destination.latitude,longitude:d.destination.longitude}}
   mode.value=d.route.mode;recommendations.value=d.parking.map(p=>({...p,traffic:d.route.traffic}));drawMarkers();drawParking();renderRoute(d.route)
  }
 }catch(e){if(token===runId&&!stopped)error.value=e.message}finally{busy.value=false}
}
function resetChat(){messages.value=[];preference.value='';endpoints.origin={text:'',point:null};endpoints.destination={text:'',point:null};invalidate();drawMarkers()}
function swap(){[endpoints.origin,endpoints.destination]=[endpoints.destination,endpoints.origin];invalidate();drawMarkers()}
function renderRoute(d){result.value=d;routeLayer.clearLayers();L.geoJSON(d.geojson,{pane:'navigation-routes',style:f=>({color:f?.properties?.segment==='walk'?'#725aad':'#1a73e8',weight:6,dashArray:f?.properties?.segment==='walk'?'7 8':undefined})}).addTo(routeLayer);const b=routeLayer.getBounds();if(b.isValid())map.fitBounds(b,{paddingTopLeft:[innerWidth>720?440:30,innerWidth>720?90:130],paddingBottomRight:[40,props.sharedMap?(innerWidth>720?250:Math.min(innerHeight*.45+110,innerHeight-230)):(innerWidth>720?70:300)],maxZoom:18})}
function body(){return {origin:endpoints.origin.point,destination:endpoints.destination.point,mode:mode.value,traffic_context:props.trafficContext}}
async function nearby(){if(!endpoints.destination.point)return;const token=runId;parkingError.value='';try{const d=await api('/navigation/parking-recommendations',{...body(),origin:endpoints.origin.point||endpoints.destination.point});if(token===runId&&!stopped){recommendations.value=d.items;drawParking();if(!d.items.length)parkingError.value='终点800米内暂无路网可达的停车区'}}catch(e){if(token===runId)parkingError.value=e.message}}
async function navigate(){if(!endpoints.origin.point||!endpoints.destination.point){error.value='请选择起点和终点';return}invalidate();busy.value=true;const token=runId;try{const d=await api('/navigation/route',body());if(token===runId&&!stopped){recommendations.value=(d.parking||[]).map(p=>({...p,traffic:d.traffic}));drawParking();renderRoute(d)}}catch(e){if(token===runId)error.value=e.message}finally{busy.value=false}}
function chooseParking(p){if(!endpoints.origin.point){directions();error.value='选择起点后可显示经此停车区的完整路线';return}renderRoute({...p,mode:mode.value,traffic:result.value?.traffic,notice:'蓝线：到停车区；紫色虚线：停车后步行。入口接驳与停车操作未计时。'})}
const sourceText=s=>s==='scenario_simulation'?'早高峰当前时刻':s==='simulated'?'模拟数据':'Qwen上传估算 · 非实时'
const color=p=>p.percent>=100?'#d93025':p.percent>=80?'#ed9300':'#188038'
function toggleLayers(){for(const [layer,visible] of [[parkingLayer,showParking.value],[percentLayer,showParking.value],[busLayer,showBus.value]]){if(!layer)continue;if(visible&&!map.hasLayer(layer))layer.addTo(map);if(!visible&&map.hasLayer(layer))map.removeLayer(layer)}}
function drawParking(){if(props.sharedMap)return;parkingLayer.clearLayers();percentLayer.clearLayers();for(const p of parkingItems.value){const layer=L.geoJSON(p.geometry,{style:{color:color(p),weight:2,fillOpacity:.18}});function popup(){const c=document.createElement('div'),b=document.createElement('b'),detail=document.createElement('p'),button=document.createElement('button');b.textContent=p.name;detail.textContent=`容载率 ${p.percent}% · 总数 ${p.count} / 容量 ${p.capacity} · 违停 ${p.illegal_count??'未分类'} · ${sourceText(p.source)} · ${new Date(p.updated_at).toLocaleString()}`;button.textContent='设为终点';button.onclick=()=>{const center=layer.getBounds().getCenter();directions();choose('destination',{name:p.name,latitude:center.lat,longitude:center.lng});map.closePopup()};c.append(b,detail,button);return c}if(recommendations.value[0]?.area_id===p.id){const label=document.createElement('span');label.textContent='推荐 · '+p.name;layer.setStyle({weight:4});layer.bindTooltip(label,{permanent:true,direction:'top'})}layer.bindPopup(popup).addTo(parkingLayer);const badge=document.createElement('span');badge.textContent=`P ${p.percent}%`;badge.style.cssText=`background:white;color:${color(p)};padding:6px 9px;border:1px solid currentColor;border-radius:16px;white-space:nowrap;font-weight:700;box-shadow:0 2px 7px #0002`;L.marker(layer.getBounds().getCenter(),{icon:L.divIcon({html:badge,className:'parking-percentage',iconSize:[90,30]}),title:p.name}).bindPopup(popup).addTo(percentLayer)}toggleLayers()}
function drawBus(){busLayer.clearLayers();for(const r of bus.value.routes){const label=document.createElement('span');label.textContent=r.name+' · '+(bus.value.vehicles.filter(v=>v.route_id===r.id).map(v=>`${v.name}：${v.observation?v.observation.count+'人 / '+v.observation.percent+'% · '+(v.observation.source==='camera'?'摄像头':'手动测试')+' · '+new Date(v.observation.captured_at).toLocaleTimeString():'暂无人数'}`).join('；')||'暂无车辆');L.polyline(r.points.map(p=>[p.latitude,p.longitude]),{color:r.color,weight:5}).bindTooltip(label).addTo(busLayer)}for(const s of bus.value.stops){const label=document.createElement('span');label.textContent=s.name;L.circleMarker([s.latitude,s.longitude],{radius:6,color:'#8b5cf6',fillColor:'white',fillOpacity:1}).bindTooltip(label,{permanent:true}).addTo(busLayer)}toggleLayers()}
async function refreshData(){const r=await Promise.allSettled([api('/parking/overview'),api('/transit')]);if(stopped)return;if(r[0].status==='fulfilled'){parkingItems.value=r[0].value.items;drawParking()}else parkingError.value='停车数据暂时无法更新';if(r[1].status==='fulfilled'){bus.value=r[1].value;drawBus()}if(endpoints.destination.point&&!result.value)nearby()}
function snapshotClock(seconds){return '08:'+String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0')}
function fitCampus(){if(roads?.getBounds().isValid())map.fitBounds(roads.getBounds(),{paddingTopLeft:[innerWidth>720?420:30,90],paddingBottomRight:[30,70]})}
function pickOnMap(e){if(picking.value&&!busy.value)choose(picking.value,{name:`地图选点 ${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`,latitude:e.latlng.lat,longitude:e.latlng.lng})}
function setupRoutePanes(){for(const [name,z] of [['navigation-routes',675],['navigation-markers',680]]){const pane=map.getPane(name)||map.createPane(name);pane.style.zIndex=z;pane.style.pointerEvents='none'}}
function closeNavigation(){invalidate();markers?.clearLayers();panel.value=false;place.value=null;ai.value=false;picking.value='';suggestions.value=[];if(props.sharedMap)emit('close')}
function replan(){if(ai.value){const last=[...messages.value].reverse().find(m=>m.role==='user');if(last){preference.value=last.content;chatNavigate()}}else navigate()}
onMounted(async()=>{if(props.sharedMap){map=props.sharedMap;setupRoutePanes();markers=L.layerGroup().addTo(map);routeLayer=L.featureGroup().addTo(map);parkingLayer=L.featureGroup();percentLayer=L.layerGroup();busLayer=L.layerGroup();map.on('click',pickOnMap);return}map=L.map(mapEl.value,{zoomControl:false,center:[0,0],zoom:16});setupRoutePanes();L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);markers=L.layerGroup().addTo(map);routeLayer=L.featureGroup().addTo(map);parkingLayer=L.featureGroup();percentLayer=L.layerGroup();busLayer=L.layerGroup();map.on('click',e=>{if(picking.value&&!busy.value)choose(picking.value,{name:`地图选点 ${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`,latitude:e.latlng.lat,longitude:e.latlng.lng})});observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(mapEl.value);try{const d=await api('/navigation/map');if(stopped)return;const named=new Set();roads=L.geoJSON(d,{style:f=>({color:f.properties.name==='修远大道'?'#e9a149':f.properties.highway==='cycleway'?'#22a447':['footway','pedestrian','steps'].includes(f.properties.highway)?'#a3947c':'#e9a149',weight:4}),onEachFeature(f,l){if(f.properties.name){const text=document.createElement('span');text.textContent=f.properties.name;l.bindTooltip(text,{permanent:!named.has(f.properties.name),direction:'center',className:'campus-road-name'});named.add(f.properties.name)}}}).addTo(map);fitCampus();await refreshData();if(!stopped)timer=setInterval(refreshData,15000)}catch(e){if(!stopped)error.value=e.message}})
onBeforeUnmount(()=>{stopped=true;clearInterval(timer);clearTimeout(searchTimer);searchId++;runId++;observer?.disconnect();if(props.sharedMap){map.off('click',pickOnMap);for(const layer of [markers,routeLayer,parkingLayer,percentLayer,busLayer])layer?.remove()}else map?.remove()})
</script>
<template>
 <main class="navigation-app" :class="{embedded:sharedMap}">
  <div v-if="!sharedMap" ref="mapEl" class="navigation-map" aria-label="校园导航地图"></div>
  <div v-if="!sharedMap" class="brand"><b>CampusFlow</b><span>长安大学 · 渭水校区</span><a href="/debug" target="_blank" rel="noopener">内部调试 ↗</a></div>
  <div class="search-shell" v-if="!panel"><MapIcon name="search" :size="22"/><input v-model="query" aria-label="搜索校园地点" placeholder="搜索宿舍、教学楼、停车区" @input="search('place')" @focus="focused='place'"><button aria-label="打开导航" title="路线" @click="directions"><MapIcon name="route"/></button><button aria-label="AI推荐" @click="openAI">AI</button><button v-if="sharedMap" aria-label="关闭地点与导航" @click="closeNavigation">×</button></div>
  <ul v-if="!panel&&focused==='place'&&suggestions.length" class="place-suggestions"><li v-for="s in suggestions" :key="s.id"><button @click="choose('place',s)">{{s.name}}</button></li></ul>
  <aside v-if="panel||place" class="navigation-panel" :class="{compact:!panel}" aria-label="地点与导航">
   <template v-if="panel"><div class="panel-head"><h1>{{ai?'AI 出行推荐':'路线规划'}}</h1><button aria-label="关闭导航" @click="closeNavigation">×</button></div>
    <template v-if="!ai"><div v-for="key in ['origin','destination']" :key="key" class="endpoint"><label :for="key">{{key==='origin'?'起点':'终点'}}</label><div class="entry"><input :id="key" v-model="endpoints[key].text" :disabled="busy" :placeholder="key==='origin'?'选择起点':'选择目的地'" @input="search(key)" @focus="focused=key"><button :disabled="busy" :class="{active:picking===key}" @click="picking=key;focused='';suggestions=[]">地图选点</button></div><ul v-if="focused===key&&suggestions.length" class="suggestions"><li v-for="s in suggestions" :key="s.id"><button @click="choose(key,s)">{{s.name}}</button></li></ul></div>
    <div class="mode-row"><button :disabled="busy" @click="swap">⇅ 交换</button><button :disabled="busy" :class="{active:mode==='walk'}" @click="mode='walk';invalidate()">步行</button><button :disabled="busy" :class="{active:mode==='bike'}" @click="mode='bike';invalidate()">骑行</button><button :disabled="busy" @click="openAI">AI 指路</button></div>
    <p v-if="picking" class="tip">点击地图设置{{picking==='origin'?'起点':'终点'}}</p><button class="primary" :disabled="busy" @click="navigate">{{busy?'正在规划…':'查找路线'}}</button></template>
    <section v-else class="ai-chat" aria-label="AI指路对话">
     <p class="muted">告诉我你在哪、要去哪，也可以补充出行偏好，无需手动选点。</p>
     <div class="chat-messages" aria-live="polite"><p v-if="!messages.length" class="chat-message assistant">你现在在哪栋楼？想去哪里？例如：我在鸿翔园5号公寓，要去明远教学楼A栋，尽量少走路。</p><p v-for="(m,i) in messages" :key="i" class="chat-message" :class="m.role">{{m.content}}</p></div>
     <form @submit.prevent="chatNavigate"><textarea v-model="preference" :disabled="busy" maxlength="2000" aria-label="告诉AI你的出行需求" placeholder="我在……，我要去……" @keydown.ctrl.enter.prevent="chatNavigate"></textarea><button class="primary" :disabled="busy||!preference.trim()" type="submit">{{busy?'正在理解并规划…':'发送并指路'}}</button></form>
     <div class="chat-actions"><button :disabled="busy" @click="resetChat">新对话</button><button :disabled="busy" @click="ai=false">普通导航</button></div>
    </section>
    <p v-if="sharedMap" class="muted">当前早高峰时刻 {{snapshotClock(trafficContext.time_seconds)}} · 可拖动底部时间轴，再次规划</p><section v-if="result" class="route-result"><strong>{{result.duration_minutes}} 分钟</strong><span>{{result.area_id?'经 '+result.name:result.mode==='walk'?'步行':'骑行'}} · {{result.distance_m}} 米</span><p v-if="result.ai">{{result.ai.reason}}</p><p>{{result.notice}}</p><p v-if="result.traffic">规划时刻 {{snapshotClock(result.traffic.time_seconds)}} · 路上 {{result.traffic.road_users}} 人 · {{result.traffic.busy_segments}} 段有流量道路</p><button v-if="sharedMap" :disabled="busy" @click="replan">按当前时刻重新规划</button></section>
   </template>
   <template v-else><div class="panel-head"><h1>{{place.name}}</h1><button aria-label="关闭地点" @click="place=null">×</button></div><p class="muted">校园地点 · {{place.location_type==='building_center'?'建筑中心':'地图位置'}}</p><button class="primary" @click="directions">到这里去</button></template>
   <section v-if="endpoints.destination.point" class="parking-results"><h2>终点附近停车区</h2><p class="muted">结合到达时间、停车后步行和容载率排序 · 800米范围</p><button v-for="(p,i) in recommendations" :key="p.area_id" class="parking-card" @click="chooseParking(p)"><b>{{i===0?'推荐 · ':''}}{{p.name}}</b><span>停车后步行 {{p.walk_minutes}} 分钟 <em :style="{color:color(p)}">{{p.percent}}%</em></span><small>{{sourceText(p.source)}} · 违停 {{p.illegal_count??'未分类'}} 辆 · 空位 {{p.free??Math.max(0,p.capacity-p.count)}} / {{p.capacity}}</small></button><p v-if="parkingError" class="muted">{{parkingError}}</p></section>
   <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="panel" class="muted">时间按步行4.5km/h、骑行12km/h估算。AI指路使用后端配置的模型。</p>
  </aside>
  <div v-if="error&&!panel&&!place" class="error floating-error" role="alert">{{error}}</div>
  <div v-if="!sharedMap" class="layer-switches" aria-label="地图显示开关"><label><input v-model="showParking" type="checkbox" @change="toggleLayers">停车区域与容载率</label><label><input v-model="showBus" type="checkbox" @change="toggleLayers">公交线路</label></div>
  <button v-if="!sharedMap" class="campus-fit" @click="fitCampus">查看全校</button><div v-if="!sharedMap" class="road-legend"><span><i style="background:#e9a149"></i>通用道路</span><span><i style="background:#22a447"></i>自行车道</span><span><i style="background:#a3947c"></i>步行道</span></div>
 </main>
</template>
<style scoped>
.navigation-app.embedded{position:absolute;inset:0;height:100%;min-height:0;z-index:800;pointer-events:none}.embedded .search-shell,.embedded .navigation-panel,.embedded .place-suggestions{pointer-events:auto}.embedded .search-shell{top:88px}.embedded .navigation-panel{top:88px;bottom:240px}.embedded .navigation-panel.compact{top:150px;bottom:auto}.embedded .place-suggestions{top:150px}@media(max-width:720px){.embedded .navigation-panel,.embedded .navigation-panel.compact{top:160px;bottom:250px;max-height:calc(100dvh - 410px)}.embedded .search-shell{top:110px}.embedded .place-suggestions{top:165px}}

.chat-messages{display:flex;flex-direction:column;gap:10px;margin:16px 0;max-height:32vh;overflow:auto}.chat-message{margin:0;padding:11px 13px;border-radius:12px;background:#f1f3f4;white-space:pre-wrap;overflow-wrap:anywhere}.chat-message.user{background:#e8f0fe;margin-left:24px}.chat-message.assistant{margin-right:12px}.chat-actions{display:flex;gap:8px;margin-top:10px}.chat-actions button{font-size:12px}

.navigation-app{height:100dvh;min-height:550px;position:relative;color:#202124;font:14px/1.5 var(--app-font)}.navigation-map{position:absolute;inset:0;background:#e9eee8}.brand{position:absolute;right:20px;top:20px;z-index:700;background:white;padding:10px 16px;border-radius:24px;display:flex;gap:12px;box-shadow:0 2px 10px #0002}.brand b{color:#1a73e8}.brand span,.brand a{font-size:11px;color:#64748b}.search-shell{position:absolute;top:20px;left:20px;width:390px;z-index:900;background:white;padding:8px 12px;border-radius:30px;box-shadow:0 3px 16px #0003;display:flex;align-items:center;gap:10px}.search-shell input{flex:1;min-width:0;border:0;padding:8px 0;outline:none}.search-shell button{color:#1a73e8;border:0!important;border-left:1px solid #ddd!important;border-radius:0!important;display:flex;align-items:center;font-weight:700}.navigation-app button{cursor:pointer;border:1px solid #dadce0;background:white;color:inherit;border-radius:20px;padding:9px 12px}.navigation-app button:disabled{opacity:.5;cursor:default}.navigation-panel{position:absolute;top:20px;left:20px;bottom:70px;width:390px;z-index:800;background:white;border-radius:18px;box-shadow:0 3px 16px #0003;padding:22px;overflow:auto}.navigation-panel.compact{top:88px;bottom:auto;max-height:calc(100dvh - 160px)}.panel-head{display:flex;align-items:center;justify-content:space-between}.panel-head h1{font-size:21px;margin:0}.endpoint{margin-top:18px}.endpoint label{font-size:12px;font-weight:600}.entry{display:flex;gap:6px;margin-top:5px}.entry input{width:100%;min-width:0;border:1px solid #dadce0;border-radius:8px;padding:11px}.entry button{white-space:nowrap;border-radius:8px;font-size:11px}.mode-row{display:flex;gap:6px;margin-top:18px}.mode-row button{font-size:12px;flex:1;padding:8px}.navigation-app button.active{background:#e8f0fe;color:#1967d2;border-color:#aecbfa}.navigation-app .primary{width:100%;background:#1a73e8;border:0;color:white;border-radius:9px;padding:13px;margin:14px 0 2px;font-weight:600}